Given an array arr[] of postive and negative integers, the objective is to find the number of subarrays having a sum exactly equal to a given number k.Examples: Input : arr[] = [10, 2, -2, -20, 10], k = -10Output : 3Explanation: Subarrays: arr[0...3], arr[1...4], arr[3...4] have sum equal to -10.Input : arr[] = [9, 4, 20, 3, 10, 5], k = 33Output : 2Explanation: Subarrays: arr[0...2], arr[2...4] have sum equal to 33.Input : arr[] = [1, 3, 5], k = 2Output : 0Explanation: No subarrays with 0 sum.Try It YourselfTable of Content[Naive Approach] Using Nested Loop - O(n^2) Time and O(1) Space[Expected Approach] Using Hash Map and Prefix Sum - O(n) Time and O(n) Space[Naive Approach] Using Nested Loop - O(n2) Time and O(1) SpaceA simple solution is to traverse all the subarrays and calculate their sum. If the sum is equal to the given number k, then increment the count of subarrays.
            C++

    #include <iostream>
#include <vector>
using namespace std;

int cntSubarrays(vector<int>& arr, int k) {

    int size = arr.size();

    // for maintaing the count of
    // subarrays whose sum equal to k
    int count = 0;
    for(int i = 0; i < size; i++){

        int currSum = 0;

        // subarray from i to each j -> arr[i....j]
        for(int j = i; j < size; j++){
            currSum += arr[j];

            // increment count if the currSum equal to k
            count += (currSum == k);
        }
    }

    return count;
}

int main() {
    vector<int> arr = {10, 2, -2, -20, 10};
    int k = -10;
    cout << cntSubarrays(arr, k);
    return 0;
}


